        uint256 pairWavaxAfter = wavax.balanceOf(SWT_WAVAX_PAIR);
        uint256 attackerProfit = ATTACKER.balance - attackerBalanceBeforeFunding - seedAmount;
        assertEq(pairWavaxAfter, 1);
